package gui

import (
	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/theme"
)

// iconFor returns the semantic icon resource for a rail slot / surface id
// (contracts/ui-contract.md §6, D3): an embedded 24x24 SVG with a stroke that
// follows the theme accent, or the stock Fyne icon as fallback when the id is
// unknown. Resources are built lazily so theme lookups happen at render time,
// never at package init (avoids "current app not started" logs).
func iconFor(id string) fyne.Resource {
	if svg, ok := iconSVGs[id]; ok {
		return fyne.NewStaticResource("letsgo-"+id+".svg", []byte(svg))
	}
	return theme.Icon(slotIconName(id))
}

// slotIconName maps a rail slot id to its stock Fyne theme icon (fallback).
func slotIconName(id string) fyne.ThemeIconName {
	switch id {
	case "chat":
		return theme.IconNameMailCompose
	case "git":
		return theme.IconNameViewRefresh
	case "tasks":
		return theme.IconNameCheckButton
	case "mcp":
		return theme.IconNameComputer
	case "plugins":
		return theme.IconNameGrid
	case "settings":
		return theme.IconNameSettings
	case "usage":
		return theme.IconNameStorage
	case "help":
		return theme.IconNameHelp
	case "theme":
		return theme.IconNameColorPalette
	case "account":
		return theme.IconNameAccount
	case "approval":
		return theme.IconNameCheckButton
	}
	return theme.IconNameQuestion
}

